// Can the installed @smartledger/bsv still read what earlier versions wrote?
//
//   node compat/check.cjs          -> every fixture in compat/fixtures, against the installed library
//   node compat/check.cjs <dir>    -> against the copy installed under <dir> (to test a candidate
//                                     version, or an OLD one against a NEW fixture before a rollback)
//
// Run after every library upgrade (npm run compat). The fixtures were each generated by the
// version in their name, through the wallet's own calls — see gen.cjs for why that matters.
// What a pass means, per fixture: that version's recovery shares still recombine on every
// 2-of-3 pair and one share alone still does not; its mnemonic still derives the same
// addresses and DID; its recovery signature is still accepted, and still REFUSED for a wrong
// signer or a changed challenge; its email credential still verifies, and a tampered one or
// one with its proof removed still does not.
const path = require("path");
const fs = require("fs");
const from = path.resolve(process.argv[2] || path.join(__dirname, ".."));
const bsv = require(require.resolve("@smartledger/bsv", { paths: [from] }));
const installed = require(require.resolve("@smartledger/bsv/package.json", { paths: [from] })).version;
console.error = () => {};

let fail = 0,
  pass = 0;
const ok = (name, cond) => {
  cond ? pass++ : fail++;
  console.log(`${cond ? "PASS" : "FAIL"}  ${name}`);
};
const refuses = (fn) => {
  try {
    return fn() === false;
  } catch {
    return true; // throwing is a refusal too
  }
};

(async () => {
  const dir = path.join(__dirname, "fixtures");
  const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
  if (files.length === 0) {
    console.log("no fixtures — nothing was checked");
    process.exit(1);
  }
  for (const f of files) {
    const a = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
    console.log(`\n== made by ${a.version}, read by ${installed}`);
    const sh = a.shares.map((s) => JSON.parse(s));
    for (const [i, j] of [[0, 1], [0, 2], [1, 2]]) {
      // combine() returns a Buffer; comparing it to the string directly is always false.
      ok(`shares ${i + 1}+${j + 1} recombine to the mnemonic`, bsv.Shamir.combine([sh[i], sh[j]]).toString() === a.mnemonic);
    }
    let single = null;
    try {
      single = bsv.Shamir.combine([sh[0]]).toString();
    } catch {
      /* refused */
    }
    ok("one share alone does not yield the mnemonic", single !== a.mnemonic);

    const hd = bsv.Mnemonic.fromString(a.mnemonic).toHDPrivateKey("", bsv.Networks.livenet);
    const idKey = hd.deriveChild("m/44'/236'/0'/0/0").privateKey;
    ok("identity address derives identically", idKey.toAddress().toString() === a.identityAddress);
    ok("token address derives identically", hd.deriveChild("m/44'/236'/2'/0/0").privateKey.toAddress().toString() === a.tokenAddress);
    ok("DID derives identically", bsv.createDID(idKey.toPublicKey()) === a.identityDid);

    ok("recovery signature accepted for the right signer", new bsv.Message(a.challenge).verify(a.identityAddress, a.signature) === true);
    ok("...refused for a wrong signer", refuses(() => new bsv.Message(a.challenge).verify(a.otherAddress, a.signature)));
    ok("...refused for a changed challenge", refuses(() => new bsv.Message(a.challenge + "x").verify(a.identityAddress, a.signature)));

    // verifyCredential is async on every version: an un-awaited call is a truthy Promise.
    const r = await bsv.verifyCredential(a.credential);
    ok("email credential verifies, naming its issuer", r.valid === true && r.issuerDID === a.issuerDid);
    const tampered = JSON.parse(JSON.stringify(a.credential));
    tampered.credentialSubject.email = "evil@x.y";
    ok("...a tampered one does not", (await bsv.verifyCredential(tampered)).valid === false);
    const stripped = JSON.parse(JSON.stringify(a.credential));
    delete stripped.proof;
    let strippedValid = false;
    try {
      strippedValid = (await bsv.verifyCredential(stripped)).valid === true;
    } catch {
      /* refused */
    }
    ok("...nor one with its proof removed", strippedValid === false);
  }
  console.log(`\n${pass} passed, ${fail} failed  (library ${installed}, ${files.length} fixture(s))`);
  process.exit(fail ? 1 : 0);
})();
